<?php session_start(); require_once "config/database.php"; if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;} $me=(int)$_SESSION['user_id']; $other=(int)($_GET['user_id']??0); $u=$pdo->prepare('SELECT id,name,role FROM users WHERE id=?');$u->execute([$other]);$otherUser=$u->fetch(PDO::FETCH_ASSOC); if(!$otherUser||$other===$me)die('Invalid conversation.'); $pdo->prepare('UPDATE messages SET is_read=1 WHERE sender_id=? AND receiver_id=?')->execute([$other,$me]); ?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php $base='';include __DIR__.'/includes/navbar.php'; ?><div class="container"><div class="details-card"><h1>Chat with <?=htmlspecialchars($otherUser['name'])?></h1><div id="chat" class="chat-box"></div><form id="sendForm"><textarea id="msg" rows="2" placeholder="Write a message..." required></textarea><button class="btn">Send</button></form></div></div><script>const other=<?=$other?>;const chat=document.getElementById('chat');async function load(){const r=await fetch('message-api.php?action=list&user_id='+other);const d=await r.json();chat.innerHTML=d.messages.map(m=>`<div class="chat-message ${m.sender_id==<?= $me ?>?'mine':''}"><strong>${m.sender_id==<?= $me ?>?'You':'<?=htmlspecialchars($otherUser['name'],ENT_QUOTES)?>'}</strong><p>${m.message.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}</p><small>${m.created_at}</small></div>`).join('');chat.scrollTop=chat.scrollHeight;}document.getElementById('sendForm').onsubmit=async e=>{e.preventDefault();let msg=document.getElementById('msg');await fetch('message-api.php?action=send',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({user_id:other,message:msg.value})});msg.value='';load();};load();setInterval(load,2000);</script></body></html>